        catch { }
    }

    // 3. Check manifest.json for local file: references
    string manifestPath = Path.Combine(unityProjectPath, "Packages", "manifest.json");
    if (File.Exists(manifestPath))
    {
        try
        {
            string manifestText = File.ReadAllText(manifestPath);
            const string searchKey = "\"com.pereviader.unityclirunner\"";
            int keyIdx = manifestText.IndexOf(searchKey, StringComparison.Ordinal);
            if (keyIdx != -1)
            {
                int fileIdx = manifestText.IndexOf("\"file:", keyIdx, StringComparison.Ordinal);
                if (fileIdx != -1 && fileIdx < manifestText.IndexOf('\n', keyIdx))
                {
