                        string packagesFolder = Path.Combine(unityProjectPath, "Packages");
                        string resolved = Path.GetFullPath(Path.Combine(packagesFolder, rel));
                        string dll1 = Path.Combine(resolved, "MCP~", "UnityCliRunner.Mcp.dll");
                        if (File.Exists(dll1)) return dll1;
                        string dll2 = Path.Combine(resolved, "MCP", "UnityCliRunner.Mcp.dll");
                        if (File.Exists(dll2)) return dll2;
                    }
