static async Task ForwardStreamAsync(Stream source, Stream destination, CancellationToken ct)
{
    byte[] buffer = new byte[4096];
    try
    {
        int bytesRead;
        while ((bytesRead = await source.ReadAsync(buffer, 0, buffer.Length, ct)) > 0)
        {
            await destination.WriteAsync(buffer, 0, bytesRead, ct);
            await destination.FlushAsync(ct);
        }
    }
    catch (OperationCanceledException) { }
    catch (Exception) { }
}

static async Task ForwardStdinAsync(Stream source, Stream destination, Process proc, CancellationToken ct)
